-- Écoles
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ucad', 'Université Cheikh Anta Diop (UCAD)', 'SN', 'Dakar', 'Publique', array['droit','sante','sciences','business','education','tech'], 50, 400, array['fr'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Université publique historique de Dakar, avec des facultés de médecine, droit, sciences, lettres et économie. Le coût est très bas pour les bacheliers sénégalais, mais les amphithéâtres sont souvent surchargés : il faut de l''autonomie pour réussir.', array['Frais quasi nuls pour les nationaux','Large choix de filières, de la licence au doctorat','Diplômes reconnus dans toute la zone CAMES'], array['Effectifs très élevés et grèves possibles qui décalent le calendrier','Logement universitaire très demandé, places limitées'], 0, 'https://www.ucad.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('cesag', 'CESAG — Centre Africain d''Études Supérieures en Gestion', 'SN', 'Dakar', 'Privée', array['business','sante'], 4500, 4500, array['fr'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Institution inter-États de l''UEMOA basée à Dakar, spécialisée en gestion, audit, comptabilité, finance et management de la santé. Promotions à taille humaine et forte présence des cabinets d''audit dans les débouchés. Les frais sont nettement plus élevés qu''à l''université publique.', array['Spécialisation pointue en audit, comptabilité et finance','Réseau d''anciens dans les cabinets et banques de la sous-région','Programmes en santé publique et management de la santé'], array['Coût élevé pour un budget faible','Offre de filières concentrée sur la gestion : peu d''options hors business et santé'], 0, 'https://www.cesag.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ism-dakar', 'ISM — Groupe Institut Supérieur de Management', 'SN', 'Dakar', 'Privée', array['business','droit','tech','comm','ingenierie'], 3500, 3800, array['fr','en'], 2, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Groupe privé avec plusieurs écoles (management, droit, ingénierie, digital). Ambiance très active, beaucoup d''étudiants de la sous-région et des formations courtes professionnalisantes. La qualité varie selon les programmes : regarde bien la reconnaissance du diplôme visé.', array['Formations courtes (BTS) à master','Vie étudiante animée et nombreux clubs','Partenariats internationaux pour des doubles diplômes'], array['Frais élevés comparés au public','Qualité et reconnaissance inégales selon les programmes'], 0, 'https://www.groupeism.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ufhb', 'Université Félix Houphouët-Boigny', 'CI', 'Abidjan', 'Publique', array['droit','sante','sciences','business','education'], 60, 500, array['fr'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Grande université publique du campus de Cocody. Très accessible financièrement pour les Ivoiriens, avec un large éventail de filières. Comme beaucoup d''universités publiques de la région, les effectifs sont importants et le calendrier peut glisser.', array['Coût très faible pour les nationaux','Grande variété de filières','Situation centrale à Abidjan, pôle économique'], array['Amphithéâtres surchargés','Peu de places en résidence universitaire'], 0, 'https://www.univ-fhb.edu.ci') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('inphb', 'Institut National Polytechnique Félix Houphouët-Boigny (INP-HB)', 'CI', 'Yamoussoukro', 'Publique', array['ingenierie','agri','business','sciences','tech'], 300, 1500, array['fr'], 2, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Grande école publique d''ingénieurs et de techniciens, recrutée sur concours très sélectif. Campus résidentiel à Yamoussoukro, encadrement plus serré qu''à l''université. Les places sont rares et la préparation au concours demande un vrai travail en maths et sciences.', array['Diplômes d''ingénieur très recherchés par les employeurs','Campus résidentiel avec vie étudiante intense','Écoles en agronomie, mines, génie civil, commerce'], array['Concours très sélectif','Ville plus calme, moins d''opportunités de stages qu''à Abidjan'], 0, 'https://www.inphb.ci') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ug-legon', 'University of Ghana', 'GH', 'Accra (Legon)', 'Publique', array['business','sciences','sante','droit','agri','comm','education'], 700, 4500, array['en'], 4, 7, 'WASSCE ou diplôme équivalent avec des crédits dans les matières clés. Les candidats internationaux postulent en ligne au guichet international.', 'Plus ancienne et plus grande université du Ghana, sur un grand campus à Legon. Enseignement en anglais, licences en 4 ans. Une bonne option anglophone dans la région, avec une vie de campus riche. Les frais internationaux sont bien plus élevés que pour les Ghanéens.', array['Enseignement en anglais en Afrique de l''Ouest','Grand campus avec halls de résidence','Large éventail de disciplines'], array['Frais internationaux élevés par rapport aux nationaux','Logement sur le campus parfois insuffisant'], 0, 'https://www.ug.edu.gh') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unilag', 'University of Lagos (UNILAG)', 'NG', 'Lagos', 'Publique', array['business','ingenierie','droit','sante','sciences','comm'], 200, 2000, array['en'], 4, 6, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Université fédérale au bord de la lagune, très demandée par les étudiants nigérians. Accès par l''examen UTME (JAMB) pour les nationaux. Lagos offre un marché du travail énorme, mais la ville est chère et embouteillée.', array['Situation au cœur du principal pôle économique d''Afrique de l''Ouest','Facultés reconnues en ingénierie, droit et business'], array['Concurrence forte à l''entrée','Coût de la vie élevé à Lagos'], 0, 'https://unilag.edu.ng') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('2ie', '2iE — Institut International d''Ingénierie de l''Eau et de l''Environnement', 'BF', 'Ouagadougou', 'Privée', array['ingenierie','agri','sciences'], 5500, 5500, array['fr','en'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'École d''ingénieurs internationale spécialisée dans l''eau, l''énergie, le génie civil et l''environnement. Étudiants de toute l''Afrique, accréditation internationale. Frais élevés pour la région, mais nombreuses bourses de partenaires.', array['Accréditation CTI et EUR-ACE','Spécialités très demandées : eau, énergie, BTP','Brassage panafricain'], array['Coût élevé sans bourse','Contexte sécuritaire régional à surveiller'], 0, 'https://www.2ie-edu.org') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('um5', 'Université Mohammed V de Rabat', 'MA', 'Rabat', 'Publique', array['droit','sante','sciences','ingenierie','business','education'], 0, 0, array['fr','ar'], 3, 8, 'Baccalauréat (ou équivalent) avec une série cohérente avec la filière. Les bacheliers nationaux passent par la plateforme nationale d''orientation ; les étudiants étrangers déposent un dossier auprès du service des étudiants étrangers ou via une bourse d''État.', 'Grande université publique de la capitale, avec médecine, ingénierie (EMI), droit et sciences. Pas de frais de scolarité dans le public ; les étudiants étrangers passent souvent par les bourses de l''AMCI. Enseignement en français et en arabe selon les filières.', array['Pas de frais de scolarité','Bourses AMCI pour de nombreux pays africains','Écoles d''ingénieurs et faculté de médecine réputées'], array['Accès des étrangers surtout via quotas et bourses','Certaines filières en arabe : vérifie la langue d''enseignement'], 0, 'https://www.um5.ac.ma') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('um6p', 'Université Mohammed VI Polytechnique (UM6P)', 'MA', 'Ben Guerir', 'Privée', array['ingenierie','tech','agri','business','sciences'], 8000, 8000, array['en','fr'], 3, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Université à but non lucratif soutenue par le groupe OCP, avec un campus moderne à Ben Guerir. Forte orientation recherche, entrepreneuriat et data. Les frais affichés sont élevés mais l''université annonce de nombreuses bourses sur critères sociaux et de mérite.', array['Campus moderne et équipements de recherche','Programmes en anglais et en français','Bourses nombreuses'], array['Ville de Ben Guerir petite et isolée','Établissement jeune : réseau d''anciens encore limité'], 0, 'https://www.um6p.ma') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uct', 'University of Cape Town (UCT)', 'ZA', 'Le Cap', 'Publique', array['sante','business','sciences','ingenierie','droit','art'], 4000, 7500, array['en'], 3, 6, 'Équivalence du diplôme via Universities South Africa (exemption), résultats suffisants dans les matières requises, anglais certifié pour les non-anglophones.', 'Université de recherche de premier plan au pied de Table Mountain. Niveau académique élevé et reconnaissance internationale. Pour les étudiants étrangers, il faut compter des frais internationaux et un coût de vie plus élevé qu''ailleurs sur le continent.', array['Reconnaissance internationale forte','Recherche de haut niveau en santé et sciences','Cadre de vie exceptionnel'], array['Coût total élevé pour un étudiant étranger','Questions de sécurité à prendre au sérieux en ville'], 0, 'https://www.uct.ac.za') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('strathmore', 'Strathmore University', 'KE', 'Nairobi', 'Privée', array['business','tech','droit','sciences'], 3500, 4200, array['en'], 4, 5, 'Baccalauréat ou équivalent. Sélection sur dossier, souvent complétée par un test écrit et un entretien de motivation.', 'Université privée de Nairobi connue pour ses programmes en commerce, finance, informatique et droit, et pour ses liens avec l''écosystème tech kényan. Encadrement exigeant et discipline académique stricte.', array['Proximité avec l''écosystème tech de Nairobi','Programmes en finance et informatique reconnus'], array['Logement sur campus limité','Cadre très strict qui ne plaît pas à tout le monde'], 0, 'https://strathmore.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ubordeaux', 'Université de Bordeaux', 'FR', 'Bordeaux', 'Publique', array['sante','sciences','droit','business','education','tech'], 200, 3150, array['fr'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Université publique pluridisciplinaire, forte en santé, sciences et droit. Les étudiants hors UE peuvent payer des frais « différenciés » (environ 3 150 $ en licence), mais de nombreuses exonérations existent. Bordeaux est une ville étudiante agréable, avec un logement plus abordable qu''à Paris.', array['Diplômes nationaux reconnus en Europe','Frais très bas pour les Européens, exonérations fréquentes','Ville étudiante à taille humaine'], array['Démarches de visa et de logement longues à anticiper','Grandes promotions en première année'], 0, 'https://www.u-bordeaux.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sorbonne', 'Sorbonne Université', 'FR', 'Paris', 'Publique', array['sciences','sante','art','education'], 200, 3150, array['fr'], 3, 8, 'Bac français : Parcoursup. Bac étranger (hors UE) : procédure « Études en France » de Campus France dans plus de 60 pays, ou demande d''admission préalable (DAP) pour une 1ère année de licence. Niveau B2 en français demandé aux non-francophones (TCF ou DELF/DALF).', 'Université de recherche issue de la fusion de Paris-Sorbonne et Pierre-et-Marie-Curie : lettres, sciences et médecine. Prestige et exigence académique au cœur de Paris. Le logement à Paris est cher et difficile à trouver.', array['Reconnaissance mondiale en sciences et lettres','Frais publics français','Vie culturelle parisienne'], array['Coût de la vie très élevé à Paris','Peu d''accompagnement individuel en licence'], 0, 'https://www.sorbonne-universite.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('sciencespo', 'Sciences Po Paris', 'FR', 'Paris', 'Publique', array['droit','business','comm','education'], 6000, 16000, array['fr','en'], 3, 5, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Établissement sélectif en sciences sociales, politiques publiques, droit et journalisme, avec des campus en région (Reims, Menton, Poitiers…) pour le Collège universitaire. Les frais dépendent des revenus pour les familles européennes ; hors UE, ils sont élevés, avec des bourses.', array['Réseau international exceptionnel','Année obligatoire à l''étranger en licence','Enseignement bilingue'], array['Très sélectif','Frais élevés hors UE'], 0, 'https://www.sciencespo.fr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('hec', 'HEC Paris', 'FR', 'Jouy-en-Josas', 'Privée', array['business'], 29000, 29000, array['en','fr'], 1, 3, 'Candidature directe auprès de l''école, très sélective. Dossier académique solide, tests standardisés selon le programme (GMAT/GRE, TAGE MAGE), anglais certifié, essais et entretiens.', 'Grande école de commerce de premier plan, sur un campus boisé près de Versailles. Programmes post-bac (Bachelor avec l''École polytechnique) et surtout masters et MBA. Les débouchés en conseil et finance sont excellents, mais l''investissement financier est lourd.', array['Réseau d''anciens très puissant','Débouchés en conseil, finance, entrepreneuriat','Campus résidentiel'], array['Coût total très élevé','Admission extrêmement sélective'], 0, 'https://www.hec.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uclouvain', 'UCLouvain', 'BE', 'Louvain-la-Neuve', 'Publique', array['sciences','sante','ingenierie','business','droit','education'], 950, 4800, array['fr','en'], 3, 7, 'Diplôme de fin de secondaire reconnu équivalent par la Fédération Wallonie-Bruxelles (demande d''équivalence obligatoire pour un diplôme étranger). Certaines filières (médecine, ingénieur civil) imposent un examen d''entrée.', 'Grande université francophone de Belgique, dans une ville piétonne entièrement pensée pour les étudiants. Les frais hors UE sont d''environ 4 800 $, avec des tarifs réduits pour les ressortissants de certains pays en développement. Très bon rapport qualité-prix en Europe.', array['Excellent rapport qualité-prix','Ville étudiante unique','Tarifs réduits pour certains pays'], array['Équivalence de diplôme obligatoire, démarche longue','Examens d''entrée pour médecine et ingénieur'], 0, 'https://uclouvain.be') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tum', 'Technische Universität München (TUM)', 'DE', 'Munich', 'Publique', array['ingenierie','tech','sciences','sante','business'], 350, 5500, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Université technique d''excellence. Depuis 2024, les étudiants hors UE paient des frais de scolarité (environ 4 300 à 6 500 $ par an selon le programme) ; les Européens ne paient qu''une contribution semestrielle. Munich est l''une des villes les plus chères d''Allemagne.', array['Niveau mondial en ingénierie et informatique','Liens forts avec l''industrie (BMW, Siemens…)','Nombreux masters en anglais'], array['Frais pour les non-Européens depuis 2024','Logement rare et cher à Munich','Licences surtout en allemand'], 0, 'https://www.tum.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('rwth', 'RWTH Aachen University', 'DE', 'Aix-la-Chapelle', 'Publique', array['ingenierie','tech','sciences'], 700, 700, array['de','en'], 3, 5, 'Le diplôme étranger doit être reconnu comme équivalent à l''Abitur. Sinon, une année de Studienkolleg (préparation) et l''examen « Feststellungsprüfung » sont nécessaires. Niveau de langue : allemand C1 (TestDaF/DSH) ou anglais pour les programmes anglophones.', 'Très grande université technique, sans frais de scolarité : seule une contribution semestrielle (environ 700 $ par an, avec titre de transport) est demandée, y compris aux étrangers. Exigeante, avec un fort taux d''échec en première année. La plupart des licences sont en allemand.', array['Pas de frais de scolarité','Réputation mondiale en ingénierie','Coût de la vie raisonnable'], array['Allemand indispensable en licence','Taux d''échec élevé les premières années','Compte bloqué d''environ 12 000 $ exigé pour le visa'], 0, 'https://www.rwth-aachen.de') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('unige', 'Université de Genève', 'CH', 'Genève', 'Publique', array['droit','sciences','sante','business','education'], 1150, 1150, array['fr','en'], 3, 6, 'Diplôme de fin d''études secondaires jugé équivalent à la maturité suisse, avec des exigences de notes et de matières. Certains diplômes imposent un examen complémentaire. Niveau de français B2 à C1 selon la faculté.', 'Frais de scolarité bas (environ 1 150 $ par an) même pour les étrangers, et proximité unique avec l''ONU et les organisations internationales. Mais Genève est l''une des villes les plus chères au monde : le budget de vie est le vrai défi.', array['Frais de scolarité bas','Écosystème des organisations internationales','Excellent niveau en droit, relations internationales, sciences'], array['Coût de la vie parmi les plus élevés au monde','Logement très difficile à trouver','Travail limité pour les étudiants hors UE'], 0, 'https://www.unige.ch') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('udem', 'Université de Montréal', 'CA', 'Montréal', 'Publique', array['sante','sciences','droit','education','art','tech'], 3000, 22000, array['fr'], 3, 7, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grande université de recherche francophone, avec HEC Montréal et Polytechnique Montréal affiliées. Les frais internationaux sont élevés (environ 22 000 $), mais des exemptions existent pour certains pays et les Français/Belges francophones paient beaucoup moins. Permis de travail après les études intéressant pour immigrer.', array['Études en français en Amérique du Nord','Voie vers le permis de travail post-diplôme','Stages coopératifs dans certains programmes'], array['Frais internationaux élevés sans exemption','Hivers rigoureux','Démarches CAQ + permis longues'], 0, 'https://www.umontreal.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('ulaval', 'Université Laval', 'CA', 'Québec', 'Publique', array['sante','sciences','agri','business','droit','education'], 3000, 22000, array['fr'], 3, 6, 'Diplôme d''études secondaires plus une année d''études supérieures pour certains systèmes (le DEC québécois sert de référence). Dossier académique, puis Certificat d''acceptation du Québec (CAQ) et permis d''études.', 'Grand campus à Québec, ville sûre et moins chère que Montréal. Programme de bourses d''excellence et d''exemption des frais majorés pour les étudiants internationaux (jusqu''à environ 25 000 $). Bonne option francophone si tu vises une bourse.', array['Bourses d''exemption pour étudiants internationaux','Ville sûre, coût de la vie modéré','Campus relié par tunnels l''hiver'], array['Frais élevés sans bourse','Marché du travail plus petit qu''à Montréal'], 0, 'https://www.ulaval.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utoronto', 'University of Toronto', 'CA', 'Toronto', 'Publique', array['sciences','tech','ingenierie','business','sante','droit','art'], 5000, 45000, array['en'], 4, 6, 'Excellent dossier secondaire, cours prérequis selon le programme, anglais certifié (IELTS/TOEFL) pour les non-anglophones. Candidature via OUAC (formulaire 105 pour l''international).', 'Université de recherche de rang mondial. Les frais internationaux sont parmi les plus élevés du Canada, mais la bourse Lester B. Pearson couvre entièrement scolarité, livres et logement pendant 4 ans pour une poignée d''élèves exceptionnels.', array['Reconnaissance mondiale','Bourse Lester B. Pearson (complète)','Toronto, grand marché du travail'], array['Frais internationaux très élevés','Logement cher à Toronto','Grandes classes en première année'], 0, 'https://www.utoronto.ca') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('mit', 'Massachusetts Institute of Technology (MIT)', 'US', 'Cambridge (Boston)', 'Privée', array['ingenierie','tech','sciences','business'], 62000, 62000, array['en'], 4, 6, 'Admission très sélective et « holistique » : notes, tests (SAT/ACT exigés au MIT), activités, essais, recommandations. Anglais certifié (TOEFL, IELTS, Duolingo English Test).', 'Référence mondiale en sciences et ingénierie. Le prix affiché est très élevé, mais l''admission est « need-blind » pour tous, y compris les étudiants internationaux, et l''aide financière couvre l''intégralité du besoin démontré. Un dossier exceptionnel est indispensable : le taux d''admission est d''environ 4 %.', array['N°1 mondial','Aide financière couvrant 100 % du besoin','Recherche et innovation sans équivalent'], array['Taux d''admission d''environ 4 %','Rythme de travail très intense'], 0, 'https://www.mit.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('utokyo', 'Université de Tokyo', 'JP', 'Tokyo', 'Publique', array['sciences','ingenierie','tech','sante','droit'], 3600, 3600, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université la plus prestigieuse du Japon. Les frais publics japonais sont modérés (environ 3 600 $ par an), et la bourse du gouvernement japonais (MEXT) peut tout couvrir. Les programmes en anglais (PEAK, masters) sont limités : une grande partie de l''enseignement reste en japonais.', array['Frais modérés pour un top mondial','Bourse MEXT complète','Recherche de pointe'], array['Peu de licences en anglais','Barrière de la langue au quotidien'], 0, 'https://www.u-tokyo.ac.jp') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('kaist', 'KAIST', 'KR', 'Daejeon', 'Publique', array['ingenierie','tech','sciences','business'], 6000, 6000, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Institut scientifique et technologique de premier plan en Corée du Sud, avec un enseignement largement en anglais. Les étudiants internationaux admis reçoivent très souvent une bourse couvrant la scolarité, voire une allocation. Ambiance très studieuse, campus résidentiel.', array['Bourses fréquentes pour les internationaux','Cours largement en anglais','Dortoirs bon marché'], array['Pression académique forte','Daejeon moins animée que Séoul'], 0, 'https://www.kaist.ac.kr') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('tsinghua', 'Université Tsinghua', 'CN', 'Pékin', 'Publique', array['ingenierie','tech','sciences','business'], 1000, 4500, array['en'], 4, 6, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université d''élite en ingénierie et sciences. Les frais internationaux restent modérés, et les bourses du gouvernement chinois (CSC) couvrent souvent tout. Les licences sont majoritairement en chinois : prévoir une année de langue, ou viser un master en anglais.', array['Excellence en ingénierie','Bourses CSC complètes','Frais modérés'], array['Chinois souvent nécessaire en licence','Accès restreint à certains services en ligne'], 0, 'https://www.tsinghua.edu.cn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('nus', 'National University of Singapore (NUS)', 'SG', 'Singapour', 'Publique', array['tech','business','ingenierie','sciences','sante','droit'], 6500, 28000, array['en'], 4, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Meilleure université d''Asie, entièrement en anglais. Avec la « Tuition Grant » du gouvernement, les frais internationaux baissent fortement, mais en échange tu t''engages à travailler 3 ans à Singapour après le diplôme. Coût de la vie élevé.', array['Top 10 mondial, tout en anglais','Hub économique asiatique','Grande sécurité'], array['Tuition Grant = engagement de 3 ans à Singapour','Admission très sélective','Vie chère'], 0, 'https://www.nus.edu.sg') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('khalifa', 'Khalifa University', 'AE', 'Abu Dhabi', 'Publique', array['ingenierie','sciences','tech','sante'], 0, 0, array['en'], 2, 5, 'Programmes en anglais accessibles avec un excellent dossier, anglais certifié et parfois un test d''entrée ou un entretien. Bourses d''État (MEXT au Japon, CSC en Chine, GKS en Corée) via l''ambassade de ton pays.', 'Université de recherche en sciences et ingénierie. Pour les masters et doctorats, des bourses complètes (frais, et souvent logement et allocation) sont proposées aux étudiants internationaux admis. Les places en licence pour les étrangers sont plus limitées.', array['Bourses complètes en master/doctorat','Laboratoires modernes','Environnement très international'], array['Surtout adaptée aux masters et doctorats','Climat très chaud'], 0, 'https://www.ku.ac.ae') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uopeople', 'University of the People', 'US', 'En ligne', 'En ligne', array['business','tech','sante','education'], 1400, 1400, array['en'], 2, 4, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'Université américaine 100 % en ligne et sans frais de scolarité : tu paies seulement des frais d''évaluation par cours (environ 1 200 à 1 600 $ par an selon le rythme). Idéale si tu dois travailler en parallèle ou si tu ne peux pas partir. Il faut beaucoup d''autonomie, et la reconnaissance du diplôme varie selon les employeurs et les pays.', array['Très faible coût, bourses possibles','Compatible avec un emploi','Accessible depuis n''importe quel pays'], array['Pas de vie de campus','Reconnaissance inégale selon les pays','Demande une forte autodiscipline'], 0, 'https://www.uopeople.edu') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('uvs', 'Université Numérique Cheikh Hamidou Kane (ex-UVS)', 'SN', 'En ligne (Sénégal)', 'En ligne', array['tech','business','education','comm','sciences'], 60, 300, array['fr'], 3, 5, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'Université publique sénégalaise qui enseigne à distance, avec des Espaces Numériques Ouverts (ENO) dans les régions pour se connecter et travailler. Très bon marché pour les bacheliers sénégalais. Il faut une bonne connexion et beaucoup d''autonomie.', array['Coût très faible','Étudier sans quitter sa région','Diplômes d''État'], array['Connexion internet indispensable','Peu d''interactions en présentiel'], 0, 'https://www.unchk.sn') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;
insert into public.ecoles (slug, nom, pays, ville, type, domaines, frais_locaux_usd, frais_etrangers_usd, langue_enseignement, duree_min, duree_max, conditions_admission, description, points_forts, points_faibles, nombre_avis, site_officiel) values ('openclassrooms', 'OpenClassrooms', 'FR', 'En ligne', 'En ligne', array['tech','business','comm','education'], 3600, 3600, array['fr','en'], 1, 2, 'Admission ouverte : diplôme de fin de secondaire (ou équivalent) et niveau de langue suffisant pour suivre les cours. Aucun déménagement nécessaire.', 'École en ligne de formations professionnalisantes courtes (développement web, data, gestion de projet…) avec mentor individuel. En alternance, la formation peut être prise en charge par l''entreprise (en France). Sinon, compter environ 300 $ par mois.', array['Formations courtes, orientées emploi','Mentor individuel','Alternance possible'], array['Pas de vie de campus','Coût non négligeable sans alternance'], 0, 'https://openclassrooms.com') on conflict (slug) do update set nom = excluded.nom, frais_locaux_usd = excluded.frais_locaux_usd, frais_etrangers_usd = excluded.frais_etrangers_usd, description = excluded.description, points_forts = excluded.points_forts, points_faibles = excluded.points_faibles;

-- Opportunités (relevé du 2026-10-10)
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-eiffel-2027', 'bourse', 'Bourse d''excellence Eiffel 2027', 'Campus France — ministère de l''Europe et des Affaires étrangères', 'FR', null, 'droit', 'Allocation mensuelle + frais annexes (voyage, assurance, activités culturelles) — montants sur la page officielle', null, 'master', '2027-01-06', 'Étudiants étrangers en master ou en doctorat. C''est l''établissement français qui dépose ton dossier.', 'https://www.campusfrance.org/fr/le-programme-de-bourses-d-excellence-eiffel', false, '{"id":"b-eiffel-2027","type":"bourse","titre":"Bourse d''excellence Eiffel 2027","organisation":"Campus France — ministère de l''Europe et des Affaires étrangères","pays":"FR","domaine":"droit","domaines":["droit","business","ingenierie","sciences","tech"],"niveau":"master","niveaux":["master","doctorat"],"montant":{"fr":"Allocation mensuelle + frais annexes (voyage, assurance, activités culturelles) — montants sur la page officielle","en":"Monthly allowance + extra costs (travel, insurance, cultural activities) — amounts on the official page"},"eligibles":{"fr":"Étudiants étrangers en master ou en doctorat. C''est l''établissement français qui dépose ton dossier.","en":"International master’s or PhD students. The French institution submits your application."},"ouverture":"2026-10-02","deadline":"2027-01-06","deadlineNote":{"fr":"Date limite pour l''établissement français qui dépose ton dossier. Ton établissement fixe une date plus tôt : demande-la-lui dès maintenant.","en":"Deadline for the French institution that submits your file. Your institution sets an earlier date: ask for it now."},"lien":"https://www.campusfrance.org/fr/le-programme-de-bourses-d-excellence-eiffel","source":"campusfrance.org","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-02', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-suisse-2027', 'bourse', 'Bourses d’excellence de la Confédération suisse 2027-2028', 'Commission fédérale des bourses (CFBE / ESKAS) — Suisse', 'CH', null, 'sciences', 'Bourse de recherche ou de doctorat (jusqu’à 36 mois pour un doctorat)', null, 'doctorat', '2026-11-30', 'Titulaires d’un master, avec un professeur en Suisse qui soutient ton projet de recherche. Dossier déposé via l’ambassade de Suisse de ton pays.', 'https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships-at-a-glance', false, '{"id":"b-suisse-2027","type":"bourse","titre":"Bourses d’excellence de la Confédération suisse 2027-2028","organisation":"Commission fédérale des bourses (CFBE / ESKAS) — Suisse","pays":"CH","domaine":"sciences","domaines":["sciences","sante","ingenierie","business","droit","education","agri","tech"],"niveau":"doctorat","niveaux":["doctorat"],"montant":{"fr":"Bourse de recherche ou de doctorat (jusqu’à 36 mois pour un doctorat)","en":"Research or PhD scholarship (up to 36 months for a PhD)"},"eligibles":{"fr":"Titulaires d’un master, avec un professeur en Suisse qui soutient ton projet de recherche. Dossier déposé via l’ambassade de Suisse de ton pays.","en":"Master’s graduates with a professor in Switzerland backing your research project. Apply through the Swiss embassy in your country."},"ouverture":"2026-08-20","deadline":"2026-11-30","deadlines":{"SN":"2026-11-30","ML":"2026-11-30","GA":"2026-11-30","CG":"2026-11-30","CD":"2026-11-30","KE":"2026-11-30","CI":"2026-11-27","CM":"2026-11-27","BJ":"2026-11-27","TG":"2026-11-27","BF":"2026-11-27","GN":"2026-11-27","NE":"2026-11-27","MG":"2026-11-27","NG":"2026-11-27","GH":"2026-11-27","DZ":"2026-11-13","MA":"2026-11-10","TN":"2026-10-13"},"deadlineNote":{"fr":"La date limite dépend de ton pays : elle est affichée pour ton pays quand il est dans la liste officielle.","en":"The deadline depends on your country: it is shown for your country when it is on the official list."},"lien":"https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships-at-a-glance","source":"sbfi.admin.ch (liste officielle Afrique, 4 août 2026)","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-08-20', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-commonwealth-master-2027', 'bourse', 'Bourses de master du Commonwealth 2027-2028', 'Commonwealth Scholarship Commission (Royaume-Uni)', 'GB', null, 'sciences', 'Billet d’avion, frais de scolarité complets et allocation de 1 712 £ par mois (2 000 £ à Londres)', null, 'master', '2026-10-20', 'Citoyens de pays du Commonwealth à revenu faible ou intermédiaire (Ghana, Kenya, Nigeria, Cameroun, Afrique du Sud…). Candidature via un organisme national qui te présente.', 'https://cscuk.fcdo.gov.uk/scholarships/commonwealth-masters-scholarships/', false, '{"id":"b-commonwealth-master-2027","type":"bourse","titre":"Bourses de master du Commonwealth 2027-2028","organisation":"Commonwealth Scholarship Commission (Royaume-Uni)","pays":"GB","domaine":"sciences","domaines":["sciences","sante","ingenierie","agri","education","business","tech"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Billet d’avion, frais de scolarité complets et allocation de 1 712 £ par mois (2 000 £ à Londres)","en":"Airfare, full tuition and a £1,712 monthly stipend (£2,000 in London)"},"eligibles":{"fr":"Citoyens de pays du Commonwealth à revenu faible ou intermédiaire (Ghana, Kenya, Nigeria, Cameroun, Afrique du Sud…). Candidature via un organisme national qui te présente.","en":"Citizens of low- and middle-income Commonwealth countries (Ghana, Kenya, Nigeria, Cameroon, South Africa…). You apply through a national nominating body."},"deadline":"2026-10-20","deadlineNote":{"fr":"Clôture le 20 octobre 2026 à 16 h (heure de Londres). L’organisme de ton pays peut fixer une date plus tôt.","en":"Closes 20 October 2026 at 16:00 UK time. Your national nominating body may set an earlier date."},"lien":"https://cscuk.fcdo.gov.uk/scholarships/commonwealth-masters-scholarships/","source":"cscuk.fcdo.gov.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-yenching-2027', 'bourse', 'Yenching Academy — master en études chinoises 2027', 'Université de Pékin (Peking University)', 'CN', null, 'droit', 'Frais de scolarité, logement, allocation mensuelle, un aller-retour en avion et voyages d’étude', null, 'master', '2026-11-30', 'Titulaires d’une licence (ou en dernière année), toutes nationalités, bon niveau d’anglais.', 'https://yenchingacademy.pku.edu.cn/ADMISSIONS.htm', false, '{"id":"b-yenching-2027","type":"bourse","titre":"Yenching Academy — master en études chinoises 2027","organisation":"Université de Pékin (Peking University)","pays":"CN","domaine":"droit","domaines":["droit","business","comm","education","art"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Frais de scolarité, logement, allocation mensuelle, un aller-retour en avion et voyages d’étude","en":"Tuition, accommodation, monthly stipend, one round-trip flight and field-study trips"},"eligibles":{"fr":"Titulaires d’une licence (ou en dernière année), toutes nationalités, bon niveau d’anglais.","en":"Bachelor’s graduates (or final-year students), any nationality, strong English."},"deadline":"2026-11-30","deadlineNote":{"fr":"Clôture le 30 novembre 2026 à 9 h, heure de Pékin (1 h du matin à Dakar).","en":"Closes 30 November 2026 at 9:00 Beijing time."},"lien":"https://yenchingacademy.pku.edu.cn/ADMISSIONS.htm","source":"yenchingacademy.pku.edu.cn","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-ens-intl-2027', 'bourse', 'Sélection internationale de l’ENS 2027', 'École normale supérieure – PSL (Paris)', 'FR', null, 'sciences', '1 000 € par mois pendant 3 ans + une chambre sur un campus de l’ENS', null, 'licence', '2026-12-15', 'Toutes nationalités, moins de 26 ans au 16 octobre 2026, au moins 1 an (sciences) ou 3 ans (lettres) d’études supérieures hors de France.', 'https://www.ens.psl.eu/en/une-formation-d-exception/admissions/international/international-selection', false, '{"id":"b-ens-intl-2027","type":"bourse","ageMax":25,"titre":"Sélection internationale de l’ENS 2027","organisation":"École normale supérieure – PSL (Paris)","pays":"FR","domaine":"sciences","domaines":["sciences","art","education","droit"],"niveau":"licence","niveaux":["licence","master"],"montant":{"fr":"1 000 € par mois pendant 3 ans + une chambre sur un campus de l’ENS","en":"€1,000 a month for 3 years + a room on an ENS campus"},"eligibles":{"fr":"Toutes nationalités, moins de 26 ans au 16 octobre 2026, au moins 1 an (sciences) ou 3 ans (lettres) d’études supérieures hors de France.","en":"Any nationality, under 26 on 16 October 2026, at least 1 year (sciences) or 3 years (humanities) of higher education outside France."},"ouverture":"2026-10-16","deadline":"2026-12-15","deadlineNote":{"fr":"Candidature du 16 octobre au 15 décembre 2026, 14 h (heure de Paris), sur la plateforme OnePSL.","en":"Apply from 16 October to 15 December 2026, 14:00 Paris time, on the OnePSL platform."},"lien":"https://www.ens.psl.eu/en/une-formation-d-exception/admissions/international/international-selection","source":"ens.psl.eu","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-16', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-eth-esop-2027', 'bourse', 'Excellence Scholarship (ESOP) — master à l’ETH Zurich', 'ETH Zurich (Suisse)', 'CH', null, 'ingenierie', '13 500 CHF par semestre + frais de scolarité offerts', null, 'master', '2026-11-30', 'Étudiants parmi les 10 % meilleurs de leur promotion de licence, qui postulent à un master de l’ETH.', 'https://ethz.ch/en/studies/financial/scholarships/excellencescholarship.html', false, '{"id":"b-eth-esop-2027","type":"bourse","titre":"Excellence Scholarship (ESOP) — master à l’ETH Zurich","organisation":"ETH Zurich (Suisse)","pays":"CH","domaine":"ingenierie","domaines":["ingenierie","sciences","tech","agri"],"niveau":"master","niveaux":["master"],"montant":{"fr":"13 500 CHF par semestre + frais de scolarité offerts","en":"CHF 13,500 per semester + tuition waiver"},"eligibles":{"fr":"Étudiants parmi les 10 % meilleurs de leur promotion de licence, qui postulent à un master de l’ETH.","en":"Students in the top 10% of their bachelor’s class applying to an ETH master’s."},"ouverture":"2026-11-01","deadline":"2026-11-30","deadlineNote":{"fr":"Candidature du 1er au 30 novembre 2026, en même temps que la candidature au master.","en":"Apply from 1 to 30 November 2026, together with your master’s application."},"lien":"https://ethz.ch/en/studies/financial/scholarships/excellencescholarship.html","source":"ethz.ch","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-11-01', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-epfl-excellence-2027', 'bourse', 'Bourses d’excellence pour le master — EPFL', 'École polytechnique fédérale de Lausanne (EPFL)', 'CH', null, 'ingenierie', '10 000 CHF par semestre, jusqu’à 4 semestres', null, 'master', '2026-12-15', 'Excellents étudiants venant d’une autre université, qui postulent à un master de l’EPFL.', 'https://www.epfl.ch/education/master/master-excellence-fellowships/how-to-apply/', false, '{"id":"b-epfl-excellence-2027","type":"bourse","titre":"Bourses d’excellence pour le master — EPFL","organisation":"École polytechnique fédérale de Lausanne (EPFL)","pays":"CH","domaine":"ingenierie","domaines":["ingenierie","sciences","tech"],"niveau":"master","niveaux":["master"],"montant":{"fr":"10 000 CHF par semestre, jusqu’à 4 semestres","en":"CHF 10,000 per semester, up to 4 semesters"},"eligibles":{"fr":"Excellents étudiants venant d’une autre université, qui postulent à un master de l’EPFL.","en":"Outstanding students from another university applying to an EPFL master’s."},"deadline":"2026-12-15","deadlineNote":{"fr":"Pour les candidats externes : dépôt avec la candidature au master, au plus tard le 15 décembre.","en":"For external applicants: submit with your master’s application by 15 December."},"lien":"https://www.epfl.ch/education/master/master-excellence-fellowships/how-to-apply/","source":"epfl.ch","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-oxford-clarendon-2027', 'bourse', 'Bourses Clarendon — Université d’Oxford 2027-2028', 'Université d’Oxford', 'GB', null, 'sciences', 'Frais de scolarité complets + allocation de vie (au moins le minimum doctoral britannique)', null, 'master', '2027-01-26', 'Toutes nationalités. Tu es examiné automatiquement si tu postules à ton master ou doctorat avant la date limite du cours.', 'https://www.ox.ac.uk/admissions/graduate/fees-and-funding/funding/clarendon/applicants', false, '{"id":"b-oxford-clarendon-2027","type":"bourse","titre":"Bourses Clarendon — Université d’Oxford 2027-2028","organisation":"Université d’Oxford","pays":"GB","domaine":"sciences","domaines":["sciences","sante","ingenierie","droit","business","art","education","tech"],"niveau":"master","niveaux":["master","doctorat"],"montant":{"fr":"Frais de scolarité complets + allocation de vie (au moins le minimum doctoral britannique)","en":"Full course fees + living grant (at least the UK minimum doctoral stipend)"},"eligibles":{"fr":"Toutes nationalités. Tu es examiné automatiquement si tu postules à ton master ou doctorat avant la date limite du cours.","en":"Any nationality. You are considered automatically if you apply to your course by its deadline."},"deadline":"2027-01-26","deadlineNote":{"fr":"La date dépend du cours : certains ferment début décembre, d’autres en janvier (ex. : 26 janvier 2027). Vérifie la page de ton cours.","en":"The date depends on the course: some close in early December, others in January (e.g. 26 January 2027). Check your course page."},"lien":"https://www.ox.ac.uk/admissions/graduate/fees-and-funding/funding/clarendon/applicants","source":"ox.ac.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-oxford-weidenfeld-2027', 'bourse', 'Bourses Weidenfeld-Hoffmann — Oxford 2027-2028', 'Université d’Oxford et Weidenfeld-Hoffmann Trust', 'GB', null, 'droit', '100 % des frais de scolarité + allocation de vie (au moins 21 805 £)', null, 'master', '2027-01-26', 'Citoyens des pays listés (presque toute l’Afrique, dont le Sénégal), pour une quarantaine de masters (politiques publiques, MBA, économie du développement, informatique…).', 'https://www.ox.ac.uk/admissions/graduate/fees-and-funding/fees-funding-and-scholarship-search/weidenfeld-hoffmann-scholarships-and-leadership-programme', false, '{"id":"b-oxford-weidenfeld-2027","type":"bourse","titre":"Bourses Weidenfeld-Hoffmann — Oxford 2027-2028","organisation":"Université d’Oxford et Weidenfeld-Hoffmann Trust","pays":"GB","domaine":"droit","domaines":["droit","business","sciences","tech","ingenierie"],"niveau":"master","niveaux":["master"],"montant":{"fr":"100 % des frais de scolarité + allocation de vie (au moins 21 805 £)","en":"100% of course fees + living grant (at least £21,805)"},"eligibles":{"fr":"Citoyens des pays listés (presque toute l’Afrique, dont le Sénégal), pour une quarantaine de masters (politiques publiques, MBA, économie du développement, informatique…).","en":"Citizens of listed countries (almost all of Africa, including Senegal), for about 40 master’s courses (public policy, MBA, development economics, computer science…)."},"deadline":"2027-01-26","deadlineNote":{"fr":"Coche la bourse dans ta candidature au master et ajoute la déclaration demandée, avant la date limite de ton cours (décembre ou janvier).","en":"Select the scholarship in your master’s application and add the required statement before your course deadline (December or January)."},"lien":"https://www.ox.ac.uk/admissions/graduate/fees-and-funding/fees-funding-and-scholarship-search/weidenfeld-hoffmann-scholarships-and-leadership-programme","source":"ox.ac.uk","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-erasmus-mundus-2027', 'bourse', 'Bourses Erasmus Mundus — masters conjoints en Europe', 'Commission européenne (EACEA)', 'EU', null, 'sciences', 'Frais de participation, voyage, visa et allocation de vie pendant tout le master (2 ans dans 2 pays ou plus)', null, 'master', '2027-01-31', 'Titulaires d’une licence, toutes nationalités. Tu postules directement au master choisi dans le catalogue.', 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', false, '{"id":"b-erasmus-mundus-2027","type":"bourse","titre":"Bourses Erasmus Mundus — masters conjoints en Europe","organisation":"Commission européenne (EACEA)","pays":"EU","domaine":"sciences","domaines":["sciences","ingenierie","tech","sante","agri","business","education","droit","art"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Frais de participation, voyage, visa et allocation de vie pendant tout le master (2 ans dans 2 pays ou plus)","en":"Participation costs, travel, visa and living allowance for the whole master’s (2 years in 2 or more countries)"},"eligibles":{"fr":"Titulaires d’une licence, toutes nationalités. Tu postules directement au master choisi dans le catalogue.","en":"Bachelor’s graduates, any nationality. You apply directly to the master’s of your choice in the catalogue."},"deadline":"2027-01-31","deadlineNote":{"fr":"Chaque master fixe sa propre date, en général entre octobre et janvier. Ouvre le catalogue et note la date de chaque master qui t’intéresse.","en":"Each master’s sets its own date, usually between October and January. Open the catalogue and note the date of each master’s you like."},"lien":"https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en","source":"eacea.ec.europa.eu","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-ubc-scholars-2027', 'bourse', 'Programme des boursiers internationaux UBC 2027', 'University of British Columbia (Canada)', 'CA', null, 'sciences', 'Bourses selon le besoin et le mérite ; la bourse Vantage One peut couvrir tout le programme et la vie sur place', null, 'licence', '2026-11-15', 'Élèves qui entrent à l’université directement après le lycée (première licence), avec un fort besoin financier, de bonnes notes et un engagement. Une recommandation de ton lycée est demandée.', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/international-scholars/', false, '{"id":"b-ubc-scholars-2027","type":"bourse","titre":"Programme des boursiers internationaux UBC 2027","organisation":"University of British Columbia (Canada)","pays":"CA","domaine":"sciences","domaines":["sciences","ingenierie","business","art","sante","tech","education","droit"],"niveau":"licence","niveaux":["licence"],"montant":{"fr":"Bourses selon le besoin et le mérite ; la bourse Vantage One peut couvrir tout le programme et la vie sur place","en":"Need- and merit-based awards; the Vantage One award can cover the full programme and living costs"},"eligibles":{"fr":"Élèves qui entrent à l’université directement après le lycée (première licence), avec un fort besoin financier, de bonnes notes et un engagement. Une recommandation de ton lycée est demandée.","en":"Students entering university straight from secondary school (first bachelor’s), with strong financial need, good grades and leadership. A school nomination is required."},"ouverture":"2026-10-05","deadline":"2026-11-15","deadlineNote":{"fr":"Dossier de bourse avant le 15 novembre 2026 ; les formulaires de ton lycée sont dus quelques jours avant.","en":"Scholarship application by 15 November 2026; your school’s forms are due a few days earlier."},"lien":"https://you.ubc.ca/financial-planning/scholarships-awards-international-students/international-scholars/","source":"you.ubc.ca","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', '2026-10-05', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-constructor-2027', 'bourse', 'Bourses Talent — Constructor University (rentrée 2027)', 'Constructor University, Brême (Allemagne)', 'DE', null, 'tech', 'Jusqu’à 100 % des frais de scolarité (la bourse JetBrains couvre aussi la vie sur place pour certaines licences en informatique)', null, 'licence', '2026-10-29', 'Avoir une offre d’admission et réussir l’examen de bourse.', 'https://constructor.university/scholarships', false, '{"id":"b-constructor-2027","type":"bourse","titre":"Bourses Talent — Constructor University (rentrée 2027)","organisation":"Constructor University, Brême (Allemagne)","pays":"DE","domaine":"tech","domaines":["tech","ingenierie","sciences","business"],"niveau":"licence","niveaux":["licence","master"],"montant":{"fr":"Jusqu’à 100 % des frais de scolarité (la bourse JetBrains couvre aussi la vie sur place pour certaines licences en informatique)","en":"Up to 100% of tuition (the JetBrains scholarship also covers living costs for some computer science bachelor’s)"},"eligibles":{"fr":"Avoir une offre d’admission et réussir l’examen de bourse.","en":"Hold an admission offer and pass the scholarship exam."},"deadline":"2026-10-29","deadlineNote":{"fr":"Examen de bourse au plus tard le 29 octobre 2026 à 14 h (UTC).","en":"Scholarship exam by 29 October 2026, 14:00 UTC."},"lien":"https://constructor.university/scholarships","source":"constructor.university","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
