insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-gates-2027', 'bourse', 'Bourse Gates Cambridge 2027-2028', 'Gates Cambridge Trust — Université de Cambridge', 'GB', null, 'sciences', 'Financement complet des études de troisième cycle à Cambridge', null, 'master', '2026-12-08', 'Étudiants hors États-Unis qui candidatent à un master ou un doctorat à temps plein à Cambridge et cochent la case Gates dans le formulaire de l’université.', 'https://www.gatescambridge.org/apply/timeline/', true, '{"id":"b-gates-2027","type":"bourse","titre":"Bourse Gates Cambridge 2027-2028","organisation":"Gates Cambridge Trust — Université de Cambridge","pays":"GB","domaine":"sciences","domaines":["sciences","sante","business","droit","ingenierie","tech","education","agri","art","comm"],"niveau":"master","niveaux":["master","doctorat"],"montant":{"fr":"Financement complet des études de troisième cycle à Cambridge","en":"Full funding for postgraduate study at Cambridge"},"eligibles":{"fr":"Étudiants hors États-Unis qui candidatent à un master ou un doctorat à temps plein à Cambridge et cochent la case Gates dans le formulaire de l’université.","en":"Non-US students applying for a full-time master’s or PhD at Cambridge who tick the Gates box in the university application."},"deadline":"2026-12-08","deadlineNote":{"fr":"8 décembre 2026 ou 6 janvier 2027 selon le master : la date exacte est indiquée pour chaque formation dans le catalogue de Cambridge.","en":"8 December 2026 or 6 January 2027 depending on the course: the exact date is shown for each course in the Cambridge course directory."},"lien":"https://www.gatescambridge.org/apply/timeline/","source":"gatescambridge.org","verifie":"2026-10-10","premium":true}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('b-mbzuai-2027', 'bourse', 'Master en intelligence artificielle — MBZUAI (rentrée 2027)', 'Mohamed bin Zayed University of Artificial Intelligence (Abou Dhabi)', 'AE', null, 'tech', 'Financement au mérite possible (non garanti) : scolarité, allocation mensuelle (15 500 AED pour les étudiants internationaux), un aller-retour par an, assurance santé, visa', null, 'master', '2026-12-15', 'Candidature au master (test de sélection en ligne). Le financement est étudié pendant l’examen du dossier.', 'https://mbzuai.ac.ae/admissions/graduate-masters-admissions', true, '{"id":"b-mbzuai-2027","type":"bourse","titre":"Master en intelligence artificielle — MBZUAI (rentrée 2027)","organisation":"Mohamed bin Zayed University of Artificial Intelligence (Abou Dhabi)","pays":"AE","domaine":"tech","domaines":["tech","ingenierie","sciences"],"niveau":"master","niveaux":["master"],"montant":{"fr":"Financement au mérite possible (non garanti) : scolarité, allocation mensuelle (15 500 AED pour les étudiants internationaux), un aller-retour par an, assurance santé, visa","en":"Merit-based funding possible (not guaranteed): tuition, monthly stipend (AED 15,500 for international students), one return flight a year, health insurance, visa"},"eligibles":{"fr":"Candidature au master (test de sélection en ligne). Le financement est étudié pendant l’examen du dossier.","en":"Apply to the master’s (online screening test). Funding is considered during the review."},"ouverture":"2026-09-07","deadline":"2026-12-15","deadlineNote":{"fr":"15 décembre 2026 pour la plupart des masters (biologie computationnelle : 22 janvier 2027).","en":"15 December 2026 for most master’s programmes (computational biology: 22 January 2027)."},"lien":"https://mbzuai.ac.ae/admissions/graduate-masters-admissions","source":"mbzuai.ac.ae","verifie":"2026-10-10","premium":true}'::jsonb, '2026-10-10', '2026-10-10', '2026-09-07', true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
