insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-villgro-africa', 'investisseur', 'Incubation Villgro Africa', 'Villgro Africa', 'AFR', null, 'sante', 'Accompagnement et financement d’amorçage pour les entreprises sociales (montants sur le site)', null, null, null, 'Entreprises en Afrique avec un premier produit, une demande prouvée, un modèle de revenus, un fondateur à plein temps et un cofondateur technique.', 'https://villgroafrica.org/innovators/apply-now/', false, '{"id":"i-villgro-africa","type":"investisseur","genre":"incubateur","titre":"Incubation Villgro Africa","organisation":"Villgro Africa","pays":"AFR","domaine":"sante","domaines":["sante","agri","tech"],"stade":"clients","montant":{"fr":"Accompagnement et financement d’amorçage pour les entreprises sociales (montants sur le site)","en":"Support and seed funding for social enterprises (amounts on the website)"},"eligibles":{"fr":"Entreprises en Afrique avec un premier produit, une demande prouvée, un modèle de revenus, un fondateur à plein temps et un cofondateur technique.","en":"Businesses in Africa with a first product, proven demand, a revenue model, a full-time founder and a technical co-founder."},"rolling":true,"rollingNote":{"fr":"Candidatures acceptées en continu ; réponse en environ un mois.","en":"Applications accepted on a rolling basis; reply in about a month."},"lien":"https://villgroafrica.org/innovators/apply-now/","source":"villgroafrica.org","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = tru