insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-antler-afrique', 'investisseur', 'Antler — résidence pour fondateurs (Lagos, Nairobi)', 'Antler', 'AFR', 'Lagos ou Nairobi', 'tech', 'Jusqu’à 250 000 $ : 100 000 $ contre 10 % de l’entreprise, puis 150 000 $ réservés pour ta levée suivante', null, null, null, 'Fondateurs seuls ou en équipe, même sans idée finale : Antler t’aide à trouver un cofondateur. Prochaine cohorte de Lagos : 15 mars 2027.', 'https://www.antler.co/apply', false, '{"id":"i-antler-afrique","type":"investisseur","genre":"accelerateur","equity":true,"titre":"Antler — résidence pour fondateurs (Lagos, Nairobi)","organisation":"Antler","pays":"AFR","ville":{"fr":"Lagos ou Nairobi","en":"Lagos or Nairobi"},"domaine":"tech","domaines":["tech","business"],"stade":"idee","montant":{"fr":"Jusqu’à 250 000 $ : 100 000 $ contre 10 % de l’entreprise, puis 150 000 $ réservés pour ta levée suivante","en":"Up to $250,000: $100,000 for 10% of the company, then $150,000 set aside for your next round"},"eligibles":{"fr":"Fondateurs seuls ou en équipe, même sans idée finale : Antler t’aide à trouver un cofondateur. Prochaine cohorte de Lagos : 15 mars 2027.","en":"Solo founders or teams, even without a final idea: Antler helps you find a co-founder. Next Lagos cohort: 15 March 2027."},"rolling":true,"rollingNote":{"fr":"On peut postuler à tout moment ; postule tôt pour réserver ta place dans une cohorte.","en":"You can apply at any time; apply early to secure a seat in a cohort."},"lien":"https://www.antler.co/apply","source":"antler.co","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = 