insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-thiel', 'investisseur', 'Thiel Fellowship', 'Thiel Foundation', 'INT', null, 'tech', '250 000 $ versés sur 2 ans, sans prise de parts', null, null, null, '22 ans maximum, sans diplôme universitaire, partout dans le monde. Accepter la bourse veut dire quitter ou mettre en pause l’université pour bâtir ton projet.', 'https://thielfellowship.org/faq', false, '{"id":"i-thiel","type":"investisseur","ageMax":22,"genre":"prix","equity":false,"titre":"Thiel Fellowship","organisation":"Thiel Foundation","pays":"INT","domaine":"tech","domaines":["tech","sciences","business","sante"],"stade":"idee","montant":{"fr":"250 000 $ versés sur 2 ans, sans prise de parts","en":"$250,000 over 2 years, no equity"},"eligibles":{"fr":"22 ans maximum, sans diplôme universitaire, partout dans le monde. Accepter la bourse veut dire quitter ou mettre en pause l’université pour bâtir ton projet.","en":"22 or younger, without a university degree, anywhere in the world. Taking it means leaving or pausing university to build your project."},"rolling":true,"rollingNote":{"fr":"Candidatures acceptées toute l’année.","en":"Applications accepted year round."},"lien":"https://thielfellowship.org/faq","source":"thielfellowship.org","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-zfellows', 'investisseur', 'Z Fellows', 'Z Fellows', 'INT', null, 'tech', 'Programme d’une semaine ; si tu le veux, 10 000 $ investis (convertis en parts lors de ta future levée)', null, null, null, 'Aucune limite d’âge, où que tu sois. Programme surtout en ligne.', 'https://www.zfellows.com/', false, '{"id":"i-zfellows","type":"investisseur","genre":"accelerateur","titre":"Z Fellows","organisation":"Z Fellows","pays":"INT","domaine":"tech","domaines":["tech","business"],"stade":"idee","montant":{"fr":"Programme d’une semaine ; si tu le veux, 10 000 $ investis (convertis en parts lors de ta future levée)","en":"One-week programme; if you want, $10,000 invested (converted into shares at your next round)"},"eligibles":{"fr":"Aucune limite d’âge, où que tu sois. Programme surtout en ligne.","en":"No age limit, wherever you are. Mostly online."},"rolling":true,"rollingNote":{"fr":"Pas de date limite : candidatures étudiées au fil de l’eau.","en":"No deadline: applications reviewed on a rolling basis."},"lien":"https://www.zfellows.com/","source":"zfellows.com","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
