insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-halcyon-ag-2027', 'investisseur', 'Accélérateur Halcyon — innovation agricole en Afrique 2027', 'Halcyon', 'AFR', 'Résidences à Accra et Nairobi', 'agri', '10 000 $ par entreprise, sans prise de parts sur cette somme, plus l’accompagnement', null, null, '2026-10-23', 'Entreprises d’agriculture ou de sécurité alimentaire en Afrique subsaharienne, avec un premier produit et des clients payants. Le dirigeant doit avoir 21 ans ou plus et parler anglais.', 'https://halcyonaccelerator.org/africa-innovation-in-ag-2027/', false, '{"id":"i-halcyon-ag-2027","type":"investisseur","ageMin":21,"genre":"accelerateur","titre":"Accélérateur Halcyon — innovation agricole en Afrique 2027","organisation":"Halcyon","pays":"AFR","ville":{"fr":"Résidences à Accra et Nairobi","en":"Residencies in Accra and Nairobi"},"domaine":"agri","domaines":["agri","tech","business"],"stade":"clients","montant":{"fr":"10 000 $ par entreprise, sans prise de parts sur cette somme, plus l’accompagnement","en":"$10,000 per venture, equity-free on that amount, plus support"},"eligibles":{"fr":"Entreprises d’agriculture ou de sécurité alimentaire en Afrique subsaharienne, avec un premier produit et des clients payants. Le dirigeant doit avoir 21 ans ou plus et parler anglais.","en":"Agriculture or food-security ventures in Sub-Saharan Africa with a first product and paying customers. The CEO must be 21+ and fluent in English."},"deadline":"2026-10-23","lien":"https://halcyonaccelerator.org/africa-innovation-in-ag-2027/","source":"halcyonaccelerator.org","verifie":"2026-10-10","premium":false}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_