insert into public.opportunites (slug, type, titre, organisation, pays, ville, domaine, montant_texte, duree, niveau_requis, date_limite, description, lien, is_premium, data, date_publication, verifie, ouverture, active) values ('i-yc-w27', 'investisseur', 'Y Combinator — promotion Winter 2027', 'Y Combinator (San Francisco)', 'US', null, 'tech', '500 000 $ (accord standard : 125 000 $ pour 7 % + 375 000 $ en SAFE)', null, null, '2026-11-02', 'Fondateurs de startups, quel que soit le pays. Programme de janvier à mars 2027 à San Francisco.', 'https://www.ycombinator.com/apply', true, '{"id":"i-yc-w27","type":"investisseur","genre":"accelerateur","equity":true,"stade":"produit","titre":"Y Combinator — promotion Winter 2027","organisation":"Y Combinator (San Francisco)","pays":"US","domaine":"tech","domaines":["tech","business","sante","agri","education"],"montant":{"fr":"500 000 $ (accord standard : 125 000 $ pour 7 % + 375 000 $ en SAFE)","en":"$500,000 (standard deal: $125,000 for 7% + $375,000 on a SAFE)"},"eligibles":{"fr":"Fondateurs de startups, quel que soit le pays. Programme de janvier à mars 2027 à San Francisco.","en":"Startup founders from any country. Programme from January to March 2027 in San Francisco."},"deadline":"2026-11-02","deadlineNote":{"fr":"2 novembre 2026, 20 h heure du Pacifique. Les candidatures envoyées après sont encore étudiées, sans garantie.","en":"2 November 2026, 8pm Pacific Time. Later applications are still reviewed, with no guarantee."},"lien":"https://www.ycombinator.com/apply","source":"ycombinator.com","verifie":"2026-10-10","premium":true}'::jsonb, '2026-10-10', '2026-10-10', null, true) on conflict (slug) do update set data = excluded.data, titre = excluded.titre, organisation = excluded.organisation, is_premium = excluded.is_premium, date_limite = excluded.date_limite, lien = excluded.lien, verifie = excluded.verifie, ouverture = excluded.ouverture, active = true;
